    {"n": 8, "titre": "Rayon de convergence et règle de d'Alembert", "notions": ["rayon"], "exos": [
        v("r1", r"Rayon de convergence de $\sum\frac{x^n}{2^n}$ ($R=\lim\left|\frac{a_n}{a_{n+1}}\right|$) ?", "limit(abs((1/2**n)/(1/2**(n+1))), n, oo)", "2",
          r"$a_n=\frac1{2^n}$, $\left|\frac{a_{n+1}}{a_n}\right|=\frac12\to\frac12$ : $R=2$."),
        v("r2", r"Rayon de convergence de $\sum\frac{n}{3^n}x^n$ ?", "limit(abs((n/3**n)/((n+1)/3**(n+1))), n, oo)", "3",
          r"$\left|\frac{a_{n+1}}{a_n}\right|=\frac{n+1}{3n}\to\frac13$ : $R=3$."),
        v("r3", r"Rayon de convergence de $\sum\frac{x^n}{n!}$ ?", "limit(abs((1/factorial(n))/(1/factorial(n+1))), n, oo)", "oo",
          r"$\left|\frac{a_{n+1}}{a_n}\right|=\frac1{n+1}\to0$ : $R=+\infty$."),
        v("r4", r"Rayon de convergence de $\sum n!\,x^n$ ?", "limit(abs(factorial(n)/factorial(n+1)), n, oo)", "0",
          r"$\left|\frac{a_{n+1}}{a_n}\right|=n+1\to+\infty$ : $R=0$ (la série ne converge qu'en $x=0$)."),
        v("r5", r"Rayon de convergence de $\sum\frac{(n!)^2}{(2n)!}x^n$ ?", "limit(abs(factorial(n)**2/factorial(2*n)/(factorial(n+1)**2/factorial(2*n+2))), n, oo)", "4",
          r"$\left|\frac{a_{n+1}}{a_n}\right|=\frac{(n+1)^2}{(2n+1)(2n+2)}=\frac{n+1}{2(2n+1)}\to\frac14$ : $R=4$."),
        v("r6", r"Rayon de convergence de $\sum(-1)^nnx^n$ ?", "limit(abs(((-1)**n*n)/((-1)**(n+1)*(n+1))), n, oo)", "1",
          r"$\left|\frac{a_{n+1}}{a_n}\right|=\frac{n+1}n\to1$ : $R=1$."),
        o("r7", r"Rayon de convergence de $\sum\frac{x^n}n$ ? Nature de la série en $x=R$ et en $x=-R$ ?",
          r"$\left|\frac{a_{n+1}}{a_n}\right|=\frac n{n+1}\to1$ : $R=1$. En $x=1$ on trouve la série harmonique $\sum\frac1n$ qui diverge ; en $x=-1$ la série $\sum\frac{(-1)^n}n$ converge (série alternée). Aucun théorème ne donne la nature en $\pm R$ : domaine de convergence $[-1,1[$.", duree=5),
        o("r8", r"Rayon de convergence de $\sum\cos(n)\,x^n$ ?",
          r"Pour $|x| < 1$ : $|\cos(n)x^n|\le|x|^n$ et $\sum|x|^n$ converge, donc la série converge absolument : $R\ge1$. Pour $|x| > 1$ : $\cos n$ ne tend pas vers $0$ (sinon $\cos 2n=2\cos^2n-1\to-1$, absurde car $(\cos 2n)$ est une suite extraite de $(\cos n)$ qui tendrait vers $0$). Il existe donc $\varepsilon > 0$ avec $|\cos n|\ge\varepsilon$ pour une infinité de $n$, et alors $|\cos(n)x^n|\ge\varepsilon|x|^n\to+\infty$ sur ces $n$ : le terme général ne tend pas vers $0$, la série diverge. Donc $R=1$ (d'Alembert ne s'applique pas : $\cos n$ s'annule presque).", duree=8),
    ]},
